def copy_legacy_rollout_percent(apps, schema_editor):
    ProviderRuntimeSetting = apps.get_model("xhs_download", "ProviderRuntimeSetting")
    for setting in ProviderRuntimeSetting.objects.all():
        rollout_percent = max(0, min(100, int(setting.rollout_percent or 0)))
        setting.douyin_ultra_rollout_percent = rollout_percent
        setting.youtube_merge_rollout_percent = rollout_percent
        setting.third_party_rollout_percent = rollout_percent
        setting.save(
            update_fields=[
                "douyin_ultra_rollout_percent",
                "youtube_merge_rollout_percent",
                "third_party_rollout_percent",
            ]
        )


def reverse_copy_legacy_rollout_percent(apps, schema_editor):
    ProviderRuntimeSetting = apps.get_model("xhs_download", "ProviderRuntimeSetting")
    for setting in ProviderRuntimeSetting.objects.all():
        setting.rollout_percent = max(
            setting.douyin_ultra_rollout_percent or 0,
            setting.youtube_merge_rollout_percent or 0,
            setting.third_party_rollout_percent or 0,
        )
        setting.save(update_fields=["rollout_percent"])


